import { beforeEach, describe, expect, test, vi } from "vitest";

/**
 * IMEで打った読みを設定資料へ効かせる（設計書6.42.2。作者の裁定、2026-10-24）。
 *
 * 確かめるのは、裁定の分かれ目が**実際の保存の口**でどう動くか——
 *
 * - AIが作った項目で読みが空 → 保存の口（人物は `saveOrUpdate`、ほかは `saveAll`）で埋める。
 *   **`autoGenerated` は true のまま**（機械が埋めた読みに作者の印を付けない）
 * - 作者が作った項目・別の読みが入っている項目 → 書かない
 * - 別名で当たった読みは、項目の読み（名前の読み）にしない
 */

interface Item {
  id: string;
  name: string;
  aliases: string[];
  reading: string | null;
  aliasReadings?: Record<string, string>;
  autoGenerated: boolean;
  updatedAt: string;
}

const characters: Item[] = [];
const locations: Item[] = [];
const saved: Array<{ via: string; record: Item }> = [];
let imeFile = { version: 1 as const, entries: [] as unknown[] };

vi.mock("../../../src/core/characterStore", () => ({
  CharacterStore: class {
    private loaded = false;
    async loadAll() {
      this.loaded = true;
      return { characters: characters.map((item) => ({ ...item })), errors: [] };
    }
    async saveOrUpdate(record: Item) {
      // 本物は読み込んだ控えが無いと「新規作成」に落ちて既存のファイルで失敗する
      if (!this.loaded) throw new Error("loadAll を済ませずに保存した");
      saved.push({ via: "saveOrUpdate", record });
    }
  },
}));

function settingsStore(source: Item[], name: string) {
  return {
    loadAll: async () => ({ records: source.map((item) => ({ ...item })), errors: [] }),
    saveAll: async (records: Item[]) => {
      for (const record of records) saved.push({ via: `${name}.saveAll`, record });
    },
  };
}

vi.mock("../../../src/core/abilityStore", () => ({
  createAbilityStore: () => settingsStore([], "ability"),
  createOrganizationStore: () => settingsStore([], "organization"),
  createLocationStore: () => settingsStore(locations, "location"),
  createWorldStore: () => settingsStore([], "world"),
}));

vi.mock("../../../src/core/imeReadingStore", () => ({
  loadImeReadings: async () => ({ file: imeFile, hash: undefined }),
  updateImeReadings: async (_work: unknown, change: (file: typeof imeFile) => typeof imeFile) => {
    imeFile = change(imeFile);
    return imeFile;
  },
}));

import {
  imeNameReadingSpans,
  invalidateImeNameCache,
  recordImeComposition,
} from "../../../src/features/imeReadings";
import type { WorkEntry } from "../../../src/models/types";

const work = { id: "w1", folderPath: "/w" } as WorkEntry;

function item(id: string, name: string, extra: Partial<Item> = {}): Item {
  return {
    id,
    name,
    aliases: [],
    reading: null,
    autoGenerated: true,
    updatedAt: "2026-10-01T00:00:00Z",
    ...extra,
  };
}

beforeEach(() => {
  characters.length = 0;
  locations.length = 0;
  saved.length = 0;
  imeFile = { version: 1, entries: [] };
  invalidateImeNameCache();
});

describe("設定資料へ書く／書かない", () => {
  test("AIが作った人物で読みが空なら、saveOrUpdate で埋める（autoGenerated は true のまま）", async () => {
    characters.push(item("char_1", "東雲"));
    const result = await recordImeComposition(work, "しののめは", "東雲は");
    expect(result.captures).toEqual([
      { surface: "東雲", reading: "しののめ", primary: "しののめ" },
    ]);
    expect(result.filled).toEqual([
      { kind: "character", id: "char_1", name: "東雲", reading: "しののめ" },
    ]);
    expect(saved).toHaveLength(1);
    expect(saved[0].via).toBe("saveOrUpdate");
    expect(saved[0].record.reading).toBe("しののめ");
    expect(saved[0].record.autoGenerated).toBe(true);
  });

  test("場所は saveAll で埋める", async () => {
    locations.push(item("loc_1", "霧ヶ峰"));
    await recordImeComposition(work, "きりがみね", "霧ヶ峰");
    expect(saved.map((entry) => entry.via)).toEqual(["location.saveAll"]);
  });

  test("作者が作った項目には書かない（控えには残る）", async () => {
    characters.push(item("char_1", "東雲", { autoGenerated: false }));
    const result = await recordImeComposition(work, "しののめ", "東雲");
    expect(result.filled).toEqual([]);
    expect(saved).toEqual([]);
    expect(imeFile.entries).toHaveLength(1);
  });

  test("別の読みが入っていれば書かない", async () => {
    characters.push(item("char_1", "東雲", { reading: "とううん" }));
    await recordImeComposition(work, "しののめ", "東雲");
    expect(saved).toEqual([]);
  });

  test("別名で当たった読みは、項目の読みにしない", async () => {
    characters.push(item("char_1", "灯", { aliases: ["姫君"] }));
    const result = await recordImeComposition(work, "ひめぎみ", "姫君");
    expect(result.captures).toEqual([
      { surface: "姫君", reading: "ひめぎみ", primary: "ひめぎみ" },
    ]);
    // 別名の読み（aliasReadings）へは埋まる（下の試し）が、名前の読みは空のまま
    expect(saved.map((entry) => entry.record.reading)).toEqual([null]);
  });

  test("別名で当たった読みは、AIが作った項目でその別名の読みが空なら別名の読みへ埋める", async () => {
    characters.push(item("char_1", "灯", { aliases: ["姫君"] }));
    const result = await recordImeComposition(work, "ひめぎみは", "姫君は");
    expect(result.filled).toEqual([
      { kind: "character", id: "char_1", name: "灯", reading: "ひめぎみ", alias: "姫君" },
    ]);
    expect(saved).toHaveLength(1);
    expect(saved[0].via).toBe("saveOrUpdate");
    expect(saved[0].record.aliasReadings).toEqual({ 姫君: "ひめぎみ" });
    // 名前の読みにはしない。作者の印も付けない
    expect(saved[0].record.reading).toBeNull();
    expect(saved[0].record.autoGenerated).toBe(true);
  });

  test("場所の別名も saveAll で埋める", async () => {
    locations.push(item("loc_1", "霧ヶ峰", { aliases: ["北の峰"] }));
    await recordImeComposition(work, "きたのみね", "北の峰");
    expect(saved.map((entry) => entry.via)).toEqual(["location.saveAll"]);
    expect(saved[0].record.aliasReadings).toEqual({ 北の峰: "きたのみね" });
  });

  test("作者が作った項目・別の読みが入っている別名には書かない", async () => {
    characters.push(item("char_1", "灯", { aliases: ["姫君"], autoGenerated: false }));
    characters.push(
      item("char_2", "東雲", { aliases: ["白雲"], aliasReadings: { 白雲: "しらくも" } })
    );
    await recordImeComposition(work, "ひめぎみ", "姫君");
    await recordImeComposition(work, "はくうん", "白雲");
    expect(saved).toEqual([]);
    expect(imeFile.entries).toHaveLength(2);
  });

  test("名前を分けた呼び方（ファイルに無い別名）には埋めない", async () => {
    // 「白樺・東雲」の「白樺」は引き当てには使うが、aliases には無い。
    // 埋めると aliases に無い鍵ができ、保存の刈り込みで消えるだけになる
    characters.push(item("char_1", "白樺・東雲"));
    const result = await recordImeComposition(work, "しらかば", "白樺");
    expect(result.captures).toEqual([
      { surface: "白樺", reading: "しらかば", primary: "しらかば" },
    ]);
    expect(saved).toEqual([]);
  });

  test("名前に当たらない変換は控えにも残さない", async () => {
    characters.push(item("char_1", "東雲"));
    await recordImeComposition(work, "かわ", "川");
    expect(imeFile.entries).toEqual([]);
    expect(saved).toEqual([]);
  });
});

/**
 * 姓と名を2回に分けて確定する打ち方（作者の実機確認、2026-10-24）。今までは
 * 1回の確定がまるごと名前・別名と一致したときしか拾わず、「白樺灯」は拾えずに
 * 別名「灯」だけが拾えていた
 */
describe("続けて打った2回の確定をつなげる", () => {
  const previous = { kana: "しらかば", committed: "白樺" };

  test("しらかば→白樺、あかり→灯 で、名前「白樺灯」と別名「灯」の両方を拾う", async () => {
    characters.push(item("char_1", "白樺灯", { aliases: ["灯"] }));
    const result = await recordImeComposition(work, "あかり", "灯", previous);
    expect(result.captures).toEqual([
      { surface: "灯", reading: "あかり", primary: "あかり" },
      { surface: "白樺灯", reading: "しらかばあかり", primary: "しらかばあかり" },
    ]);
    // AIが作った項目で読みが空なので、別名「灯」は別名の読みへ、つないだ「白樺灯」は
    // 名前の読みへ埋める（別名の読みを名前の読みにしない）
    expect(saved.map((entry) => [entry.record.reading, entry.record.aliasReadings])).toEqual([
      [null, { 灯: "あかり" }],
      ["しらかばあかり", undefined],
    ]);
    expect(result.filled).toEqual([
      { kind: "character", id: "char_1", name: "白樺灯", reading: "あかり", alias: "灯" },
      { kind: "character", id: "char_1", name: "白樺灯", reading: "しらかばあかり" },
    ]);
  });

  test("作者の項目（autoGenerated: false）には書かず、控えに残して提案にする", async () => {
    characters.push(item("char_1", "白樺灯", { aliases: ["灯"], autoGenerated: false }));
    const result = await recordImeComposition(work, "あかり", "灯", previous);
    expect(saved).toEqual([]);
    expect(result.filled).toEqual([]);
    expect(imeFile.entries).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ surface: "白樺灯", reading: "しらかばあかり", count: 1 }),
      ])
    );
  });

  test("つないで当たったのが別名なら、別名の読みの決まりに乗る（AIが作った項目で空なら埋める）", async () => {
    characters.push(item("char_1", "レン", { aliases: ["黒瀬蓮"] }));
    const result = await recordImeComposition(work, "れん", "蓮", {
      kana: "くろせ",
      committed: "黒瀬",
    });
    expect(result.filled).toEqual([
      { kind: "character", id: "char_1", name: "レン", reading: "くろせれん", alias: "黒瀬蓮" },
    ]);
    expect(saved[0].record.aliasReadings).toEqual({ 黒瀬蓮: "くろせれん" });
    expect(saved[0].record.reading).toBeNull();
  });

  test("つないで当たった別名でも、作者の項目には書かない（控えに残して提案にする）", async () => {
    characters.push(item("char_1", "レン", { aliases: ["黒瀬蓮"], autoGenerated: false }));
    await recordImeComposition(work, "れん", "蓮", { kana: "くろせ", committed: "黒瀬" });
    expect(saved).toEqual([]);
    expect(imeFile.entries).toEqual([
      expect.objectContaining({ surface: "黒瀬蓮", reading: "くろせれん" }),
    ]);
  });

  test("前の確定を渡さなければ、今までどおり単独の確定だけを見る", async () => {
    characters.push(item("char_1", "白樺灯", { aliases: ["灯"] }));
    const result = await recordImeComposition(work, "あかり", "灯");
    expect(result.captures.map((capture) => capture.surface)).toEqual(["灯"]);
    // 埋まるのは別名「灯」の読みだけ（名前の読みは空のまま）
    expect(saved.map((entry) => entry.record.reading)).toEqual([null]);
  });

  test("前の確定「白樺」が別の項目の名前でも、つないだ組で二重に数えない", async () => {
    characters.push(item("char_1", "白樺灯"));
    locations.push(item("loc_1", "白樺", { reading: "しらかば" }));
    // 1回目：「白樺」だけの確定（場所の名前として拾う。読みは同じなので書かない）
    await recordImeComposition(work, "しらかば", "白樺");
    // 2回目：「灯」を続けて確定
    await recordImeComposition(work, "あかり", "灯", previous);
    const counts = Object.fromEntries(
      (imeFile.entries as Array<{ surface: string; count: number }>).map((entry) => [
        entry.surface,
        entry.count,
      ])
    );
    expect(counts).toEqual({ 白樺: 1, 白樺灯: 1 });
  });
});

describe("読み上げの範囲", () => {
  test("設定資料の読みが勝ち、空ならIMEの控えを使う", async () => {
    characters.push(item("char_1", "東雲", { reading: "しののめ" }));
    characters.push(item("char_2", "白樺", { autoGenerated: false }));
    imeFile = {
      version: 1,
      entries: [
        { surface: "東雲", reading: "しの", count: 9, lastSeen: "2026-10-24T00:00:00Z" },
        { surface: "白樺", reading: "しらかば", count: 1, lastSeen: "2026-10-24T00:00:00Z" },
      ],
    };
    const text = "東雲と白樺。";
    const { spans } = await imeNameReadingSpans(work, text);
    expect(spans).toEqual([
      { start: 0, end: 2, reading: "しののめ" },
      { start: 3, end: 5, reading: "しらかば" },
    ]);
  });

  test("設定資料の別名の読みが、IMEの控えより先に別名へ当たる", async () => {
    characters.push(
      item("char_1", "灯", { aliases: ["姫君"], aliasReadings: { 姫君: "ひめぎみ" } })
    );
    imeFile = {
      version: 1,
      entries: [{ surface: "姫君", reading: "ひめ", count: 9, lastSeen: "2026-10-24T00:00:00Z" }],
    };
    const { spans } = await imeNameReadingSpans(work, "姫君が来た。");
    expect(spans).toEqual([{ start: 0, end: 2, reading: "ひめぎみ" }]);
  });
});
